using System;
namespace Downfield {
public class TradeReview {public bool Accepted;public int Fee,Offered,Required;public string Reason="";}
public partial class Franchise {
 public float MarketValue(ClubPlayer p){float value=28+(p.OVR-70)*4.5f+(p.OVR>=90?(p.OVR-89)*4:0);value+=(Math.Min(99,p.Potential)-p.OVR)*(p.Age<27?1.8f:.35f);value+=(27-p.Age)*2.2f;value+=Math.Min(3,p.Years)*3;value+=Math.Max(-15,Math.Min(12,(ContractSalary(p.OVR)-p.Salary)*1.5f));if(p.Role=="QB")value*=1.22f;value*=Math.Max(.4f,1-p.InjuryWeeks*.095f);return Math.Max(10,value);}
 public TradeReview EvaluateTrade(ClubPlayer give,ClubPlayer get){TradeReview r=new TradeReview();if(give==null||get==null||give.Team!=UserTeam||get.Team<0||get.Team==UserTeam){r.Reason="Choose a player from each team.";return r;}int team=get.Team;float offered=MarketValue(give),required=MarketValue(get);LeagueTeam cpu=Teams[team];ClubPlayer replacement=null;foreach(ClubPlayer p in Squad(team))if(p.Id!=get.Id&&p.Role==get.Role&&p.InjuryWeeks==0&&(replacement==null||p.OVR>replacement.OVR))replacement=p;bool fillsHole=give.Role==get.Role;int best=0;foreach(ClubPlayer p in Squad(team))if(p.Id!=get.Id&&p.Role==give.Role)best=Math.Max(best,p.OVR);offered+=Math.Max(-20,Math.Min(18,(give.OVR-best)*1.2f));if(cpu.BuildPlan=="REBUILD"){offered+=give.Age<=25?10:-5;required+=get.Age<=25?10:0;}if(cpu.BuildPlan=="CONTEND"&&get.Slot>=0)required+=8;if(get.Slot>=0&&!fillsHole&&(replacement==null||replacement.OVR<get.OVR-7))required+=25;if(get.Role=="QB"&&get.Slot==0&&!fillsHole&&(replacement==null||replacement.OVR<78))required+=35;r.Offered=(int)Math.Round(offered);r.Required=(int)Math.Ceiling(required);float gap=required-offered;r.Fee=2+(int)Math.Ceiling(Math.Max(0,gap)/4);if(Round>=8)r.Reason="Trade deadline has passed.";else if(get.OVR>=90&&give.OVR<get.OVR-7)r.Reason="They want a star in return.";else if(gap>Math.Max(12,required*.12f))r.Reason="They need more player value.";else if(Payroll(UserTeam)-give.Salary+get.Salary>Cap)r.Reason="Your team would be over the cap.";else if(Payroll(team)-get.Salary+give.Salary>Cap)r.Reason="Their team cannot afford this salary.";else if(Credits<r.Fee)r.Reason="You need $"+r.Fee+"M to finish the deal.";else{r.Accepted=true;r.Reason="They will accept / $"+r.Fee+"M fee";}return r;}
 void FillTradeVacancy(int team,int slot,ClubPlayer incoming){if(slot<0)return;if(Roles[slot]==incoming.Role){incoming.Slot=slot;return;}ClubPlayer best=null;foreach(ClubPlayer p in Squad(team))if(p.Slot<0&&p.Role==Roles[slot]&&(best==null||p.OVR>best.OVR))best=p;if(best!=null)best.Slot=slot;}
 public bool ExecuteTrade(int outgoing,int incoming){if(!CanManageClub())return false;ClubPlayer a=Players.Find(p=>p.Id==outgoing),b=Players.Find(p=>p.Id==incoming);TradeReview review=EvaluateTrade(a,b);if(!review.Accepted){Notice=review.Reason;return false;}int other=b.Team,aslot=a.Slot,bslot=b.Slot;a.Team=other;b.Team=UserTeam;a.Slot=b.Slot=-1;FillTradeVacancy(UserTeam,aslot,b);FillTradeVacancy(other,bslot,a);if(b.Slot<0){int weak=WeakestSlot(UserTeam,b.Role);ClubPlayer old=Starter(UserTeam,weak);if(weak>=0&&(old==null||old.OVR<b.OVR)){if(old!=null)old.Slot=-1;b.Slot=weak;}}if(a.Slot<0){int weak=WeakestSlot(other,a.Role);ClubPlayer old=Starter(other,weak);if(weak>=0&&(old==null||old.OVR<a.OVR)){if(old!=null)old.Slot=-1;a.Slot=weak;}}Credits-=review.Fee;EnsureJerseyNumbers();Log("Traded "+a.Role+" "+a.Name+" for "+b.Role+" "+b.Name+" / $"+review.Fee+"M.");Save();return true;}
}
}
